import SwiftUI

/// The website's own icon set (inc/icons.php) — the same vectors as the Android app, so the icons look identical.
/// Generated from SiteIcons.kt by scratch/genicons.py.
struct SiteIcon: View {
    let name: String
    var size: CGFloat = 24
    var color: Color? = nil
    var body: some View {
        Canvas { ctx, sz in
            let k = sz.width / 24
            ctx.scaleBy(x: k, y: k)
            let col: GraphicsContext.Shading = color.map { .color($0) } ?? .foreground
            for e in SiteIcons.data[name] ?? SiteIcons.data["dots"] ?? [] {
                var p = Path(); e.build(&p)
                if e.f == 1 { ctx.fill(p, with: col) } else if e.f == 2 { ctx.fill(p, with: .color(.white)) }
                if e.s > 0 { ctx.stroke(p, with: e.s == 2 ? .color(.white) : col, style: StrokeStyle(lineWidth: e.w, lineCap: .round, lineJoin: .round)) }
            }
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}
